import process from 'node:process';
import { randomUUID } from 'node:crypto';
import { connectDatabase } from '../../src/infrastructure/database/database';
import { isolatedQueues } from './queues';

// Only the database generated by this invocation may be removed.
const name = `integration_${randomUUID().replaceAll('-', '')}`;
const admin = await connectDatabase();
let queues: Awaited<ReturnType<typeof isolatedQueues>> | undefined;
try {
  queues = await isolatedQueues();
  await admin.em.fork().execute(`CREATE DATABASE "${name}"`);
  const url = new URL(
    process.env.DATABASE_URL ??
      'postgresql://jungle:jungle@localhost:5432/jungle',
  );
  url.pathname = `/${name}`;
  const isolated = await connectDatabase(url.toString());
  try {
    await isolated.migrator.up();
  } finally {
    await isolated.close();
  }
  const child = Bun.spawn(
    [process.execPath, 'test', 'test/integration', '--timeout', '30000'],
    {
      env: {
        ...process.env,
        DATABASE_URL: url.toString(),
        SQS_ENDPOINT: queues.configuration.endpoint,
        SQS_QUEUE_URL: queues.configuration.incoming,
        SQS_EVENTS_URL: queues.configuration.events,
        SQS_DLQ_URL: queues.configuration.dlq,
      },
      stdout: 'inherit',
      stderr: 'inherit',
    },
  );
  const terminate = () => child.kill('SIGTERM');
  process.once('SIGINT', terminate);
  process.once('SIGTERM', terminate);
  try {
    process.exitCode = await child.exited;
  } finally {
    process.removeListener('SIGINT', terminate);
    process.removeListener('SIGTERM', terminate);
  }
} finally {
  try {
    await queues?.close();
  } finally {
    try {
      await admin.em
        .fork()
        .execute(`DROP DATABASE IF EXISTS "${name}" WITH (FORCE)`);
    } finally {
      await admin.close();
    }
  }
}
